import { useState, useSyncExternalStore } from "react";

/* Example dates count from when they appear. An app takes its dates from its data. */

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/** A fixed moment for server rendering, so the server and the browser write the same HTML. */
const reference = Date.UTC(2026, 0, 15, 12);

const subscribe = () => () => {
  // Whether the page has hydrated never changes back.
};

const useDemoClock = () => {
  // oxlint-disable-next-line react/hook-use-state -- the time is read once, when the example appears, and never replaced.
  const [appeared] = useState(() => Date.now());

  return useSyncExternalStore(
    subscribe,
    () => appeared,
    () => reference,
  );
};

export { DAY, HOUR, MINUTE, useDemoClock };

import { RelativeTime } from "@/registry/erbium/ui/relative-time";
import type { RelativeTimeProps } from "@/registry/erbium/ui/relative-time";
import { DAY, HOUR, MINUTE, useDemoClock } from "../examples/use-demo-clock";

/** How far from now each choice is. */
export const distances = {
  "-2 years": -740 * DAY,
  "-3 hours": -3 * HOUR,
  "-26 hours": -26 * HOUR,
  now: 0,
  "+5 minutes": 5 * MINUTE,
  "+4 days": 4 * DAY,
  "+2 months": 65 * DAY,
};

type PlaygroundProps = Pick<
  RelativeTimeProps,
  "format" | "formatStyle" | "locale" | "maxUnits" | "numeric"
> & { distance: keyof typeof distances };

export const defaultProps = {
  distance: "-3 hours",
  format: "relative",
  formatStyle: "long",
  locale: "en",
  maxUnits: 1,
  numeric: "auto",
} satisfies PlaygroundProps;

export default function RelativeTimePlaygroundExample({
  distance,
  ...props
}: PlaygroundProps = defaultProps) {
  const now = useDemoClock();

  return <RelativeTime date={now + distances[distance]} className="text-title" {...props} />;
}
